1	import java.util.ArrayList;
2	import java.util.List;
3	
4	/**
5	 * A class representing shared characteristics of animals,
6	 * could be initialised for prey animals.
7	 *
8	 * @version 2022.02.28
9	 */
10	
11	public class Animal extends Species
12	{
13	    // Fields defining a special kind of animal, they can not be changed after initialization
14	
15	    // The age at which an animal can start to breed.
16	    private final int breedingAge;
17	    // The age to which an animal can live.
18	    private final int maxAge;
19	    // The maximum number of births at once.
20	    private final int maxLitterSize;
21	    // true if the animal's sex if female
22	    private final boolean isFemale;
23	    // true if the animal hibernates during cold temperatures
24	    private final boolean hibernates;
25	    // true if the animal is active at night
26	    private final boolean isNocturnal;
27	    // the number of steps that should pass until an animal in hibernation moves
28	    private static final int STAY_STEPS = 10;
29	    // foodLevel cap as a multiple of nutritional value — above this threshold the animal stops eating
30	    private static final double FOOD_LEVEL_FULL_MULTIPLIER = 1.5;
31	    // Temperature offset above minimum at which hibernating animals enter hibernation
32	    private static final int HIBERNATION_TEMPERATURE_OFFSET = 5;
33	    // Divisor used to compute the lower bound of a newborn's initial food level
34	    private static final int INITIAL_FOOD_LEVEL_MIN_DIVISOR = 2;
35	
36	    // Fields prone to change during the animal's life
37	
38	    // The animal's food level
39	    private int foodLevel;
40	    // number of steps where the animal is in hibernation
41	    private int hiberSteps;
42	    // true if the animal is currently hibernating
43	    private boolean inHibernation;
44	    // The animal's age.
45	    private int age;
46	
47	    /**
48	     * Create a new animal with given specifications. An animal can be created with random age (or start at age 0) and
49	     * with a random foodLevel.
50	     *
51	     * @param field (Field) the field where the simulation takes place
52	     * @param location (Location) the Location at which the animal should appear
53	     * @param name (String) the animal's name (its species' name)
54	     * @param maximumTemperature (int) the maximum temperature the animal can survive to
55	     * @param minimumTemperature (int) the minimum temperature an animal can survive to
56	     * @param nutritionalValue (int) the animal's nutritional value
57	     * @param reproductionProbability (double) the probability that the animal reproduces at each step after a given minimum breeding age
58	     * @param maxAge (int) the animal's life expectancy
59	     * @param breedingAge (int) the age at which animal can start to reproduce
60	     * @param maxLitterSize (int) the maximum number of children the animal can have in one reproduction
61	     * @param randomAge (boolean) whether an animal should be created with a random age
62	     * @param hibernates (boolean) whether an animal is able to hibernate
63	     * @param isNocturnal (boolean) whether an animal is more active at night
64	     */
65	    public Animal(Field field, Location location, String name, int maximumTemperature, int minimumTemperature, int nutritionalValue, double reproductionProbability, int maxAge, int breedingAge, int maxLitterSize, boolean randomAge, boolean hibernates, boolean isNocturnal)
66	    {
67	        super(field, location, name, maximumTemperature, minimumTemperature, nutritionalValue, reproductionProbability);
68	
69	        this.breedingAge = breedingAge;
70	        this.maxAge = maxAge;
71	        this.maxLitterSize = maxLitterSize;
72	        this.isFemale = randomSex();
73	        this.hibernates = hibernates;
74	        this.isNocturnal = isNocturnal;
75	        // Default value is nutritionalValue to simulate the nutriment apart from the mother's milk/ other parental feeding.
76	        this.foodLevel = randomFoodLevel();
77	        inHibernation = false;
78	        hiberSteps = 0;
79	
80	        if (randomAge) {
81	            age = rand.nextInt(maxAge);
82	        } else {
83	            age = 0;
84	        }
85	    }
86	
87	    /**
88	     * Imitate an animal's step by doing the following:
89	     * 1) increment the animal's age if a year has passed.
90	     * 2) if the animal is alive, then:
91	     *      i) check if the animal should hibernate.
92	     *      ii) if the animal is in hibernation, then:
93	     *          a) if it passed STAY_STEPS steps without moving, then move and increment hunger.
94	     *          b) increment hiberSteps.
95	     *      iii) if the animal can't withstand the current temperature, then it dies.
96	     *      iv) if the animal is not in hibernation, then:
97	     *          a) if it is night and the animal is nocturnal, then move.
98	     *          b) if it is day, then all animals move and increment hunger.
99	     *
100	     * @param newSpecies (List<Species>) A list to receive newly born animals.
101	     * @param isNight (boolean) true if it is night in the simulation
102	     * @param temperature (int) the current temperature of the simulation
103	     * @param yearPassed true if a year has passed in the simulation
104	     */
105	    public void act(List<Species> newSpecies, boolean isNight, int temperature, boolean yearPassed, boolean isSpring, boolean seasonChanged)
106	    {
107	        // 1)
108	        if (yearPassed) {
109	            incrementAge();
110	        }
111	
112	        // 2)
113	        if(isAlive())
114	        {
115	            // i)
116	            checkHibernation(temperature);
117	            
118	            // ii)
119	            if (inHibernation)
120	            {
121	                // a)
122	                if (hiberSteps % STAY_STEPS == 0) {
123	                    makeMove(newSpecies);
124	                    if (isAlive()) {
125	                        incrementHunger();
126	                    }
127	                }
128	                // b)
129	                incrementHiberSteps();
130	            }
131	            // iii)
132	            else if (! survivesTemperature(temperature))
133	            {
134	                setDead();
135	            }
136	            // iv) All animals act during the day; nocturnal animals also act at night.
137	            else
138	            {
139	                if (!isNight || isNocturnal) {
140	                    makeMove(newSpecies);
141	                }
142	                if (!isNight && isAlive()) {
143	                    incrementHunger();
144	                }
145	            }
146	        }
147	    }
148	
149	    /**
150	     * An animal's movement. It first tries to reproduce, then to eat if a plant is in one of the neighboring cells and finally to move
151	     * if an adjacent cell is available. If no adjacent cell is available, it dies of overcrowding.
152	     *
153	     * @param newSpecies (List<Species>) A list to receive newly born animals.
154	     */
155	    protected void makeMove(List<Species> newSpecies)
156	    {
157	        ArrayList<Animal> neighboringAnimalsList = getNeighboringAnimalsList();
158	
159	        if (canReproduce(neighboringAnimalsList)) {
160	            reproduce(newSpecies);
161	        }
162	
163	        // Eats if it is possible
164	        if (canEat()) {
165	            findFoodAndEat();
166	        }
167	
168	        // Find a free location in adjacent cells
169	        Location newLocation = getField().freeAdjacentLocation(getLocation());
170	
171	        // See if it was possible to move.
172	        if(newLocation != null) {
173	            setLocation(newLocation);
174	        }
175	        else {
176	            // Overcrowding.
177	            setDead();
178	        }
179	    }
180	
181	    /**
182	     * Returns a list of animals located in neighboring cells.
183	     *
184	     * @return (ArrayList) list of neighboring animals
185	     */
186	    protected ArrayList<Animal> getNeighboringAnimalsList()
187	    {
188	        ArrayList<Animal> neighboringAnimals = new ArrayList<>();
189	        for (Location where : getField().adjacentLocations(getLocation())) {
190	            Species species = getField().getObjectAt(where);
191	            if (species instanceof Animal) {
192	                Animal neighboringAnimal = (Animal) species;
193	                if (neighboringAnimal.isAlive()) {
194	                    neighboringAnimals.add(neighboringAnimal);
195	                }
196	            }
197	        }
198	        return neighboringAnimals;
199	    }
200	
201	    /**
202	     * Increase the age. This could result in the animal's death.
203	     */
204	    protected void incrementAge()
205	    {
206	        age++;
207	        if(age > maxAge) {
208	            setDead();
209	        }
210	    }
211	
212	    /**
213	     * Make this animal more hungry. This could result in the animal's death.
214	     */
215	    protected void incrementHunger()
216	    {
217	        foodLevel--;
218	        if(foodLevel <= 0) {
219	            setDead();
220	        }
221	    }
222	    
223	    /**
224	     * @return (boolean) true if the animal can eat (food level below the fullness threshold).
225	     */
226	    protected boolean canEat()
227	    {
228	        return foodLevel < getNutritionalValue() * FOOD_LEVEL_FULL_MULTIPLIER;
229	    }
230	    
231	    /**
232	     * Increment hiberSteps by 1
233	     */
234	    protected void incrementHiberSteps()
235	    {
236	        hiberSteps++;
237	    }
238	
239	    /**
240	     * Look for plants adjacent to the current location.
241	     * Only the first plant is eaten.
242	     */
243	    private void findFoodAndEat()
244	    {
245	        for (Location where : getField().adjacentLocations(getLocation())) {
246	            Species species = getField().getObjectAt(where);
247	            if (species instanceof Plant) {
248	                Plant plant = (Plant) species;
249	                if (plant.isAlive()) {
250	                    plant.eaten();
251	                    incrementFoodLevel(plant.getNutritionalValue());
252	                    break;
253	                }
254	            }
255	        }
256	    }
257	
258	    /**
259	     * If the animal is a female, check if a male of the same species is in one of the neighboring cells. If it is the case, animal is able to reproduce
260	     *  and should go to the cel where the male is.
261	     *  Note: The task of reproducing is handled only by females so that the same reproduction can not happen twice in the same simulator step.
262	     *
263	     * @param  neighboringAnimalsList (ArrayList<Animal>) Array List of the Animal objects located in neighboring cells.
264	     * @return (boolean) if animal can reproduce.
265	     *
266	     */
267	    protected boolean canReproduce(ArrayList<Animal> neighboringAnimalsList)
268	    {
269	        // Reproduction is handled only by females to prevent the same pair from reproducing twice per step.
270	        if (!this.isFemale || !canGiveBirth()) {
271	            return false;
272	        }
273	        for (Animal neighbor : neighboringAnimalsList) {
274	            if (!neighbor.isFemale && neighbor.getName().equals(this.getName())) {
275	                return true;
276	            }
277	        }
278	        return false;
279	    }
280	
281	    /**
282	     * Creates the appropriate number of animals of the same species. These new animals of course share the same features as their "parent"
283	     * except the sex which is randomized,  their age and foodLevel are not randomized.
284	     *
285	     * @param  speciesInSimulation (List<Species>) List of Species objects in the simulation for the newborns to be added to it.
286	     */
287	    protected void reproduce(List<Species> speciesInSimulation)
288	    {
289	        Field field = getField();
290	        if (field != null)
291	        {
292	            List<Location> free = field.getFreeAdjacentLocations(getLocation());
293	            int births = numberOfBirths();
294	            for(int b = 0; b < births && free.size() > 0; b++) {
295	                Location loc = free.remove(0);
296	                Animal young = new Animal(field, loc, getName(), getMaximumTemperature(), getMinimumTemperature(), getNutritionalValue(), getReproductionProbability(), maxAge, breedingAge, maxLitterSize,false, hibernates, isNocturnal);
297	                speciesInSimulation.add(young);
298	            }
299	        }
300	    }
301	
302	    /**
303	     * Returns a random boolean to randomize the sex of newborns.
304	     *
305	     * @return true if female, otherwise false (male)
306	     */
307	    private boolean randomSex()
308	    {
309	        return rand.nextBoolean();
310	    }
311	    
312	    /**
313	     * Return a random foodLevel more than the animal's nutritional value divided by half.
314	     *
315	     * @return (int) the foodLevel.
316	     */
317	    private int randomFoodLevel()
318	    {
319	        int lowBound = getNutritionalValue() / INITIAL_FOOD_LEVEL_MIN_DIVISOR;
320	        return rand.nextInt(lowBound) + lowBound;
321	    }
322	
323	    /**
324	     * Generate a number representing the number of births, if it can breed.
325	     *
326	     * @return (int) The number of births (can be zero).
327	     */
328	    protected int numberOfBirths()
329	    {
330	        int births = 0;
331	        if(canGiveBirth() && rand.nextDouble() <= getReproductionProbability()) {
332	            births = rand.nextInt(maxLitterSize) + 1;
333	        }
334	        return births;
335	    }
336	
337	    /**
338	     * An animal can give birth if it has reached the minimal breeding age.
339	     */
340	    protected boolean canGiveBirth()
341	    {
342	        return age >= breedingAge;
343	    }
344	
345	    /**
346	     * Check if the animal should be in hibernation.
347	     *
348	     * Change inHibernation to true if the animal can hibernate
349	     * and the current temperature is less than or equal the
350	     * minimum temperature of the animal + 5
351	     *
352	     * @param currentTemperature (int) the current temperature of the simulation
353	     */
354	    protected void checkHibernation(int currentTemperature)
355	    {
356	        if (hibernates && currentTemperature <= getMinimumTemperature() + HIBERNATION_TEMPERATURE_OFFSET) {
357	            inHibernation = true;
358	        }
359	        else {
360	            inHibernation = false;
361	            hiberSteps = 0;
362	        }
363	    }
364	
365	    /**
366	     * @return (int) The maximum age to which an animal can live
367	     */
368	    protected int getMaxAge ()
369	    {
370	        return maxAge;
371	    }
372	
373	    /**
374	     * @return (int) The age at which an animal can start to breed
375	     */
376	    protected int getBreedingAge ()
377	    {
378	        return breedingAge;
379	    }
380	
381	    /**
382	     * @return (int) The maximum number of births at once
383	     */
384	    protected int getMaxLitterSize ()
385	    {
386	        return maxLitterSize;
387	    }
388	
389	    /**
390	     * @return (boolean) true if the animal hibernates
391	     */
392	    protected boolean getHibernates()
393	    {
394	        return hibernates;
395	    }
396	
397	    /**
398	     * @return (boolean) true if the animal is active at night
399	     */
400	    protected boolean getIsNocturnal()
401	    {
402	        return isNocturnal;
403	    }
404	
405	    /**
406	     * Increments the animal's food level by a given number (the nutritional value of the food he just ate).
407	     * It is public because a predator's food level can be incremented another predator in the case that it attacks it.
408	     *
409	     * @param value (int) the number to increment foodLevel by.
410	     */
411	    public void incrementFoodLevel(int value) {
412	        foodLevel += value;
413	    }
414	
415	}
