1	/**
2	 * This class reads from "animals.csv" the information about all the animals
3	 * that are available to be put in the simulation.
4	 *
5	 * @version 2022.02.28
6	 */
7	
8	public class AnimalCSVReader extends CSVReader
9	{
10	    // Path to the file holding the animal related data.
11	    private static final String FILE_NAME = "animals.csv";
12	    // String to be recognized as a boolean value of true.
13	    private static final String TRUE_SYMBOL = "true";
14	    // true if the animal is a predator.
15	    private boolean isPredator;
16	    // Animal's name.
17	    private String name;
18	    // Maximum temperature the animal can survive to.
19	    private int maximumTemperature;
20	    // Minimum temperature the animal can survive to.
21	    private int minimumTemperature;
22	    // Maximum Age animal can live for.
23	    private int maximumAge;
24	    // Minimum age at which animal can breed.
25	    private int breedingAge;
26	    // Probability to see animal breed at each step.
27	    private double breedingProbability;
28	    // Maximum litter size brought by animal in one reproduction.
29	    private int maxLitterSize;
30	    // Nutritional value brought when animal is eaten.
31	    private int nutritionalValue;
32	    // Animal's strength (0 if not a predator).
33	    private int strength;
34	    // Whether an animal can hibernate.
35	    private boolean hibernates;
36	    // Whether an animal is nocturnal.
37	    private boolean isNocturnal;
38	    /**
39	     * Builds an AnimalCSVReader and initializes field.
40	     */
41	    public AnimalCSVReader() {
42	        resetParameters();
43	    }
44	
45	    /**
46	     * Populated fields with the data read from the files. This method overrides
47	     * a method of the CSVReader parent class and is therefore called after reading the data.
48	     *
49	     * @param extractedData (String[]) The data read.
50	     */
51	    protected void populateFields(String[] extractedData)
52	    {
53	        if (extractedData.length != 12) {
54	            ErrorThrower.throwMessage("Animal .csv issue, please restart.");
55	            return;
56	        }
57	        name               = extractedData[0];
58	        isPredator         = TRUE_SYMBOL.equals(extractedData[1]);
59	        maximumTemperature = Integer.parseInt(extractedData[2]);
60	        minimumTemperature = Integer.parseInt(extractedData[3]);
61	        maximumAge         = Integer.parseInt(extractedData[4]);
62	        breedingAge        = Integer.parseInt(extractedData[5]);
63	        breedingProbability = Double.parseDouble(extractedData[6]);
64	        maxLitterSize      = Integer.parseInt(extractedData[7]);
65	        nutritionalValue   = Integer.parseInt(extractedData[8]);
66	        strength           = Integer.parseInt(extractedData[9]);
67	        hibernates         = TRUE_SYMBOL.equals(extractedData[10]);
68	        isNocturnal        = TRUE_SYMBOL.equals(extractedData[11]);
69	    }
70	
71	    /**
72	     * Set all parameters back to their initial values before reading data for another animal.
73	     */
74	    protected void resetParameters()
75	    {
76	        isPredator = false;
77	        name = null;
78	        maximumTemperature = 0;
79	        minimumTemperature = 0;
80	        maximumAge = 0;
81	        breedingAge = 0;
82	        breedingProbability = 0;
83	        maxLitterSize = 0;
84	        nutritionalValue = 0;
85	        strength = 0;
86	        hibernates = false;
87	        isNocturnal = false;
88	
89	    }
90	
91	    /**
92	     * @return (String) The name of the file containing habitat data.
93	     */
94	    protected String getFileName() {
95	        return FILE_NAME;
96	    }
97	
98	    /**
99	     * @return (String) The animal's name.
100	     */
101	    public String getName() {
102	        return name;
103	    }
104	
105	    /**
106	     * @return (double) Probability that the animal breeds at a given step.
107	     */
108	    public double getBreedingProbability() {
109	        return breedingProbability;
110	    }
111	
112	    /**
113	     * @return (int) Maximum age animal can live for.
114	     */
115	    public int getMaximumAge() {
116	        return maximumAge;
117	    }
118	
119	    /**
120	     * @return (int) Maximum temperature animal can survive to.
121	     */
122	    public int getMaximumTemperature() {
123	        return maximumTemperature;
124	    }
125	
126	    /**
127	     * @return (int) Minimum age for animal to start breeding.
128	     */
129	    public int getBreedingAge() {
130	        return breedingAge;
131	    }
132	
133	    /**
134	     * @return (int) Minimum temperature animal can survive to.
135	     */
136	    public int getMinimumTemperature() {
137	        return minimumTemperature;
138	    }
139	
140	    /**
141	     * @return (int) Maximum litter size brought by animal in one reproduction.
142	     */
143	    public int getMaxLitterSize() {
144	        return maxLitterSize;
145	    }
146	
147	    /**
148	     * @return (int) Nutritional value brought when animal is eaten.
149	     */
150	    public int getNutritionalValue() {
151	        return nutritionalValue;
152	    }
153	
154	    /**
155	     * @return (int) Animal's strength (0 if not a predator).
156	     */
157	    public int getStrength() {
158	        return strength;
159	    }
160	
161	    /**
162	     * @return (boolean) If animal is a predator.
163	     */
164	    public boolean isPredator() {
165	        return isPredator;
166	    }
167	
168	    /**
169	     * @return (boolean) Whether or not animal can hibernate.
170	     */
171	    public boolean canHibernate() {
172	        return hibernates;
173	    }
174	
175	    /**
176	     * @return (boolean) Whether or not animal is nocturnal.
177	     */
178	    public boolean isNocturnal()
179	    {
180	        return isNocturnal;
181	    }
182	}
183

1	/**
2	 * An enum that specifies the values and actions of the different
3	 * climate change scenarios to approximate the real scenarios projected by the IPCC.
4	 *
5	 * @version 2022.02.28
6	 */
7	public enum ClimateScenarios
8	{
9	    SCENARIO1("none", 0, 0), SCENARIO2("low", 1, 0.05), SCENARIO3("medium", 2, 0.15), SCENARIO4("high", 3, 0.3);
10	
11	    private final String label;
12	    private double concreteChange;
13	    private final double initialConcreteChange;
14	    private final double changePercentage;
15	
16	    /**
17	     * Create an appropriate Climate Scenario
18	     *
19	     * @param label (String) the user-facing name for this scenario
20	     * @param concreteChange (int) hold the actual temperature change value
21	     * @param changePercentage (double) the change percentage that is added to the concreteChange each year
22	     */
23	    ClimateScenarios(String label, int concreteChange, double changePercentage)
24	    {
25	        this.label = label;
26	        this.concreteChange = concreteChange;
27	        this.initialConcreteChange = concreteChange;
28	        this.changePercentage = changePercentage;
29	    }
30	
31	    /**
32	     * @return (String) the user-facing label for this scenario
33	     */
34	    public String getLabel()
35	    {
36	        return label;
37	    }
38	
39	    /**
40	     * Return the scenario whose label matches the given string, defaulting to SCENARIO1 (no change).
41	     *
42	     * @param label (String) the label to look up
43	     * @return (ClimateScenarios) the matching scenario
44	     */
45	    public static ClimateScenarios fromLabel(String label)
46	    {
47	        for (ClimateScenarios s : values()) {
48	            if (s.label.equals(label)) return s;
49	        }
50	        return SCENARIO1;
51	    }
52	    
53	    /**
54	     * @return (int) the concreteChange as a rounded int
55	     */
56	    public int getClimateChangeEffect()
57	    {
58	        return (int) Math.round(concreteChange);
59	    }
60	
61	    /**
62	     * Increases the concreteChange by the changePercentage.
63	     */
64	    public void doClimateChange()
65	    {
66	        concreteChange = concreteChange + (changePercentage * concreteChange);
67	    }
68	
69	    /**
70	     * Reset concreteChange to its initial value so each simulation run starts from the base scenario.
71	     */
72	    public void reset()
73	    {
74	        concreteChange = initialConcreteChange;
75	    }
76	}
