1	/**
2	 * Provide a counter for a participant in the simulation.
3	 *
4	 * @version 2022.02.28
5	 */
6	public class Counter
7	{
8	    // How many of this type exist in the simulation.
9	    private int count;
10	
11	    /**
12	     * Initialise the counter at zero.
13	     */
14	    public Counter()
15	    {
16	        count = 0;
17	    }
18	
19	    /**
20	     * @return (int) The current count for this type.
21	     */
22	    public int getCount()
23	    {
24	        return count;
25	    }
26	
27	    /**
28	     * Increment the current count by one.
29	     */
30	    public void increment()
31	    {
32	        count++;
33	    }
34	
35	    /**
36	     * Reset the current count to zero.
37	     */
38	    public void reset()
39	    {
40	        count = 0;
41	    }
42	}
