1	import java.util.HashMap;
2	
3	/**
4	 * This class collects and provides some statistical data on the state 
5	 * of a field. It is flexible: it will create and maintain a counter 
6	 * for any name of species that is found in the field.
7	 *
8	 * @version 2022.03.01
9	 */
10	public class FieldStats
11	{
12	    // Counters for each type of entity in the simulation.
13	    private HashMap<String, Counter> counters;
14	    // Whether the counters are currently up to date.
15	    private boolean countsValid;
16	
17	    /**
18	     * Construct a FieldStats object.
19	     */
20	    public FieldStats()
21	    {
22	        // Set up a collection for counters for each type of specie that
23	        // we might find
24	        counters = new HashMap<>();
25	        countsValid = true;
26	    }
27	
28	    /**
29	     * Check if species count is valid.
30	     *
31	     * @param field (Field) The simulation's field.
32	     */
33	    public void checkCountIsValid(Field field)
34	    {
35	        if(!countsValid) {
36	            generateCounts(field);
37	        }
38	    }
39	    /**
40	     * Get details of what is in the field.
41	     *
42	     * @return (String) A string describing what is in the field.
43	     */
44	    public int getCount(String speciesName)
45	    {
46	        Counter info = counters.get(speciesName);
47	        return info != null ? info.getCount() : 0;
48	    }
49	    
50	    /**
51	     * Invalidate the current set of statistics; reset all counts to zero.
52	     */
53	    public void reset()
54	    {
55	        countsValid = false;
56	        for(String key : counters.keySet()) {
57	            Counter count = counters.get(key);
58	            count.reset();
59	        }
60	    }
61	
62	    /**
63	     * Increment the count for one specie.
64	     *
65	     * @param specieName (String) The name of specie to increment.
66	     */
67	    public void incrementCount(String specieName)
68	    {
69	        Counter count = counters.get(specieName);
70	        if(count == null) {
71	            // We do not have a counter for this specie yet.
72	            // Create one.
73	            count = new Counter();
74	            counters.put(specieName, count);
75	        }
76	        count.increment();
77	    }
78	
79	    /**
80	     * Indicate that a specie count has been completed.
81	     */
82	    public void countFinished()
83	    {
84	        countsValid = true;
85	    }
86	
87	    /**
88	     * Determine whether the simulation is still viable. I.e., should it continue to run.
89	     *
90	     * @return (boolean) true If there is more than one species alive.
91	     */
92	    public boolean isViable(Field field)
93	    {
94	        // How many counts are non-zero.
95	        int nonZero = 0;
96	        if(!countsValid) {
97	            generateCounts(field);
98	        }
99	        for(String key : counters.keySet()) {
100	            Counter info = counters.get(key);
101	            if(info.getCount() > 0) {
102	                nonZero++;
103	            }
104	        }
105	        return nonZero > 1;
106	    }
107	    
108	    /**
109	     * Generate counts of the number of species. These are not kept up to date as species are placed in the field, but only when a request
110	     * is made for the information.
111	     * @param field (Field) The field to generate the stats for.
112	     */
113	    private void generateCounts(Field field)
114	    {
115	        reset();
116	        for(int row = 0; row < field.getDepth(); row++) {
117	            for(int col = 0; col < field.getWidth(); col++) {
118	                Species specie = field.getObjectAt(row, col);
119	                if(specie != null) {
120	                    incrementCount(specie.getName());
121	                }
122	            }
123	        }
124	        countsValid = true;
125	    }
126	}
