7	 * all the GUI's interactions with the simulation's "backend".
8	 *
9	 * @version 2022.02.28
10	 */
11	public class GUIHandler
12	{
13	    private Initializer simulationInitializer;
14	    private Simulator simulatorOnDisplay;
15	    private JFrame currentFrame;
16	    private ArrayList<String> animalChoices;
17	    private ArrayList<String> habitatChoices;
18	    private ArrayList<String> scenarioChoices;
19	
20	    /**
21	     * Build a GUIHandler with appropriate lists of choices for animals, habitats, and climate change scenarios.
22	     *
23	     * @param animalChoices (ArrayList<String>) List of animal choices.
24	     * @param habitatChoices (ArrayList<String>) List of habitat choices.
25	     * @param scenarioChoices (ArrayList<String>) List of climate change scenario choices.
26	     */
27	    public GUIHandler (Initializer initializer, ArrayList<String> animalChoices, ArrayList<String> habitatChoices, ArrayList<String> scenarioChoices)
28	    {
29	        simulationInitializer = initializer;
30	        this.animalChoices = animalChoices;
31	        this.habitatChoices = habitatChoices;
32	        this.scenarioChoices = scenarioChoices;
33	        showMenuView();
34	    }
35	
36	    /**
37	     * Set the menuView as the view currently on screen. The menu view is the view
38	     * that allows the user to set their choices concerning the simulation to be run.
39	     */
40	    private void showMenuView()
41	    {
42	        MenuView menuViewMaker = new MenuView(this, animalChoices, habitatChoices, scenarioChoices);
43	        JFrame menuFrame = menuViewMaker.createAndShow();
44	        menuFrame.pack();
45	        menuFrame.setVisible(true);
46	        currentFrame = menuFrame;
