103	    }
104	}

1	import java.util.ArrayList;
2	import java.util.List;
3	import java.util.Random;
4	
5	
6	/**
7	 * Represent a habitat of the simulation.
8	 * Keep track of its seasons and temperature.
9	 *
10	 * @version 2022.02.28
11	 */
12	public class Habitat
13	{
14	    // holds the habitat's seasons
15	    private List<Season> seasons;
16	    // the number of steps before the season changes
17	    private static final int SEASON_CHANGE = 50;
18	    // hold the current season
19	    private Season currentSeason;
20	    // keep track of the simulation steps.
21	    private SimulationStep simStep;
22	    // hold a climate change scenario
23	    private ClimateScenarios changeScenario;
24	    // true if the current season is Spring
25	    private boolean isSpring;
26	    // A random number generator
27	    private static final Random rand = Randomizer.getRandom();
28	
29	    /**
30	     * Initialise the Habitat fields and fill the
31	     * seasons Hash map
32	     *
33	     * @param simStep (SimulatorStep) A SimulationStep object to keep track of the steps
34	     * @param changeScenario (ClimateScenarios) A climate change scenario
35	     * @param spring (int[]) An integer array with two elements: [0]= spring aveTemperature, [1] = spring tempChange
36	     * @param summer (int[]) An  integer array with two elements: [0]= summer aveTemperature, [1] = summer tempChange
37	     * @param autumn (int[]) An  integer array with two elements: [0]= autumn aveTemperature, [1] = autumn tempChange
38	     * @param winter (int[]) An  integer array with two elements: [0]= winter aveTemperature, [1] = winter tempChange
39	     */
40	    public Habitat(SimulationStep simStep, ClimateScenarios changeScenario, int[] spring, int[] summer, int[] autumn, int[] winter)
41	    {
42	        this.simStep = simStep;
43	        this.changeScenario = changeScenario;
44	
45	        // Season initialisations
46	        initialiseSeasons(spring, summer, autumn, winter);
47	        currentSeason = seasons.get(0);   // the simulation always starts with spring
48	        isSpring = true;
49	        changeScenario.reset(); // reset scenario to base value so each simulation starts fresh
50	        climateChangeEffect(); // do the climate change effect on the first season
51	    }
52	
53	    /**
54	     * @return (String) The current season as a String
55	     */
56	    public String getCurrentSeason()
57	    {
58	        return currentSeason.getName();
59	    }
60	
61	    /**
62	     * @return (int) The current temperature of the current season as an int
63	     */
64	    public int getCurrentTemperature()
65	    {
66	        return currentSeason.getCurrentTemperature();
67	    }
68	
69	    /**
70	     * @return (boolean) true if the current season is spring, false otherwise.
71	     */
72	    public boolean getIsSpring()
73	    {
74	        return isSpring;
75	    }
76	
77	    /**
78	     * @return (boolean) true if a year has passed in the simulation, false otherwise
79	     */
80	    public boolean yearPassed()
81	    {
82	        int step = simStep.getCurrentStep();
83	        // step+1 because step starts with 0
84	        return step != 0 && (step+1) % (SEASON_CHANGE * 4) == 0;
85	    }
86	
87	    /**
88	     * @return (boolean) true if the season changed on this simulation step, false otherwise
89	     */
90	    public boolean seasonJustChanged()
91	    {
92	        int step = simStep.getCurrentStep();
93	        return step != 0 && step % SEASON_CHANGE == 0;
94	    }
95	
96	    /**
97	     * Method to be called on every step of the simulation for habitat conditions to be updated.
98	     *
99	     * 1) Increase the climate change effect if a year has passed
100	     * 2) Change the season if 'SEASON_CHANGE' steps have passed.
101	     * 3) Do the climate change effect on the new season
102	     * 4) Change the temperature each step
103	     */
104	    public void habitatStep()
105	    {
106	        int step = simStep.getCurrentStep();
107	
108	        // 1)
109	        if(yearPassed())
110	        {
111	            changeScenario.doClimateChange();
112	        }
113	
114	        // 2) & 3)
115	        if(step != 0 && step % SEASON_CHANGE == 0)
116	        {
117	            changeSeason();
118	            checkIsSpring();
119	            climateChangeEffect();
120	        }
121	
122	        // 4)
123	        randomizeTemperature();
124	    }
125	
126	    /**
127	     * Create and initialise the appropriate Season objects with the given values. Add them to the seasons List with the
128	     * order: spring, summer, autumn, winter.
129	     *
130	     * @param springValues (int[]) An integer array with two elements: [0]= spring aveTemperature, [1] = spring tempChange
131	     * @param summerValues (int[]) An integer array with two elements: [0]= summer aveTemperature, [1] = summer tempChange
132	     * @param autumnValues (int[]) An integer array with two elements: [0]= autumn aveTemperature, [1] = autumn tempChange
133	     * @param winterValues (int[]) An integer array with two elements: [0]= winter aveTemperature, [1] = winter tempChange
134	     */
135	    private void initialiseSeasons(int[] springValues, int[] summerValues, int[] autumnValues, int[] winterValues)
136	    {
137	        Season spring = new Season("spring", springValues[0], springValues[1]);
138	        Season summer = new Season("summer", summerValues[0], summerValues[1]);
139	        Season autumn = new Season("autumn", autumnValues[0], autumnValues[1]);
140	        Season winter = new Season("winter", winterValues[0], winterValues[1]);
141	
142	        // Initialise seasons and fill it
143	        seasons = new ArrayList<>();
144	        seasons.add(spring);
145	        seasons.add(summer);
146	        seasons.add(autumn);
147	        seasons.add(winter);
148	    }
149	
150	    /**
151	     * Change the current season according to the predefined order of seasons
152	     */
153	    private void changeSeason()
154	    {
155	        int seasonIndx = seasons.indexOf(currentSeason);
156	
157	        if(seasonIndx == seasons.size() -1) {
158	            currentSeason = seasons.get(0);
159	        }
160	        else {
161	            currentSeason = seasons.get(seasonIndx + 1);
162	        }
163	    }
164	
165	    /**
166	     * Make isSpring true or false depending on the current season.
167	     */
168	    private void checkIsSpring()
169	    {
170	        isSpring = currentSeason == seasons.get(0);
171	    }
172	
173	    /**
174	     * Change the current season's temperature randomly according to the season's tempChange field
175	     */
176	    private void randomizeTemperature()
177	    {
178	        int randomize = rand.nextInt(2);
179	        int change = rand.nextInt(currentSeason.getTempChange() + 1);
180	
181	        // make sure that the temperature doesn't go beyond the temperature upper limit
182	        if (randomize == 0 && (getCurrentTemperature() + change) <= currentSeason.getUpperLimitTemp()) {
183	            currentSeason.incrementCurrentTemperature(change);
184	        }
185	        // make sure that the temperature doesn't go below the temperature lower limit
186	        else if (randomize == 1 && (getCurrentTemperature() - change) >= currentSeason.getLowerLimitTemp()) {
187	            currentSeason.incrementCurrentTemperature(-change);
188	        }
189	    }
190	
191	    /**
192	     * Increase the season's average temperature by the climate change scenario's concreteChange
193	     */
194	    private void climateChangeEffect()
195	    {
196	        currentSeason.incAveTemperature(changeScenario.getClimateChangeEffect());
197	    }
198	}

