33	    private static final int AUTUMN_TEMP_CHANGE_IDX = 7;
34	    private static final int PLANT_CONCENTRATION_IDX = 8;
35	    private static final int EXPECTED_FIELD_COUNT    = 9;
36	
37	    /**
38	     * Build a HabitatCSVReader and initialize its fields.
39	     */
40	    public HabitatCSVReader() {
41	        winterTemperatures = new int[2];
42	        autumnTemperatures = new int[2];
43	        springTemperatures = new int[2];
44	        summerTemperatures = new int[2];
45	        plantConcentration = 0;
46	    }
