48	    /**
49	     * Populate the fields with the data extracted from the .csv file. Fields are used to store data of the right type to be easily fetched
50	     * by the Initializer when trying to get information about a specific habitat.
51	     * Habitat name from the data is removed to facilitate reading, the first 12 elements are in groups of 2 relating to each season
52	     * (average temperature, and maximum change to temperature ), the 13th element is the plant concentration in that habitat.
53	     *
54	     * @param extractedData (String[]) the data from the CSV file relative to a specific habitat.
55	     */
56	    protected void populateFields(String[] extractedData)
57	    {
58	        extractedData = removeHabitatName(extractedData);
59	        if (extractedData.length != EXPECTED_FIELD_COUNT) {
60	            ErrorThrower.throwMessage("Habitat issue, please restart.");
61	            return;
62	        }
63	
64	        winterTemperatures[0] = Integer.parseInt(extractedData[WINTER_AVG_TEMP_IDX]);
65	        winterTemperatures[1] = Integer.parseInt(extractedData[WINTER_TEMP_CHANGE_IDX]);
66	        springTemperatures[0] = Integer.parseInt(extractedData[SPRING_AVG_TEMP_IDX]);
67	        springTemperatures[1] = Integer.parseInt(extractedData[SPRING_TEMP_CHANGE_IDX]);
68	        summerTemperatures[0] = Integer.parseInt(extractedData[SUMMER_AVG_TEMP_IDX]);
69	        summerTemperatures[1] = Integer.parseInt(extractedData[SUMMER_TEMP_CHANGE_IDX]);
70	        autumnTemperatures[0] = Integer.parseInt(extractedData[AUTUMN_AVG_TEMP_IDX]);
71	        autumnTemperatures[1] = Integer.parseInt(extractedData[AUTUMN_TEMP_CHANGE_IDX]);
72	        plantConcentration    = Double.parseDouble(extractedData[PLANT_CONCENTRATION_IDX]);
73	    }
74	
75	    /**
76	     * Set all parameters back to initial values before reading data for another habitat.
77	     */
78	    protected void resetParameters()
79	    {
80	        winterTemperatures = new int[2];
81	        springTemperatures = new int[2];
82	        summerTemperatures = new int[2];
83	        autumnTemperatures = new int[2];
84	        plantConcentration = 0;
85	
86	    }
87	
88	    /**
89	     * Returns the list of extracted data without the habitat's name (as this informaiton is known by the Initializer and will therefore
90	     * not be asked). The name is the first element of the attributes list.
91	     *
92	     * @param attributes (String[]) the data from the CSV file relative to a specific habitat.
93	     * @return (String[]) The data without the habitat's name.
94	     */
95	    private String[] removeHabitatName(String[] attributes)
96	    {
97	        String[] attributesWithoutHabitatName = Arrays.copyOfRange(attributes,1,attributes.length);
98	        return attributesWithoutHabitatName;
99	    }
100	
101	    /**
102	     * @return (String) The name of the file containing habitat data.
103	     */
104	    protected String getFileName() {
105	        return FILE_NAME;
106	    }
107	
108	    /**
109	     * @return (int[]) Minimum, average, and maximum temperatures for the winter.
110	     */
111	    public int[] getWinterTemperatures()
112	    {
113	        return winterTemperatures;
114	    }
115	
116	    /**
117	     * @return (int[]) Minimum, average, and maximum temperatures for the autumn.
118	     */
119	    public int[] getAutumnTemperatures() {
120	        return autumnTemperatures;
121	    }
122	
123	    /**
124	     * @return (int[]) Minimum, average, and maximum temperatures for the spring.
125	     */
126	    public int[] getSpringTemperatures() {
127	        return springTemperatures;
128	    }
129	
130	    /**
131	     * @return (int[]) Minimum, average, and maximum temperatures for the summer.
132	     */
133	    public int[] getSummerTemperatures() {
134	        return summerTemperatures;
135	    }
136	
137	    /**
138	     * @return (double) The concentration of plants in the habitat.
139	     */
140	    public double getPlantConcentration() {
141	        return plantConcentration;
142	    }
143	}

