7	/**
8	 * Initializing the simulation. It first launches the UI, then builds the appropriate
9	 * objects to run the simulation desired by the user.
10	 *
11	 * IMPORTANT: This is the class that should be called to run the simulation.
12	 *
13	 * @version 2022.03.01
14	 */
15	public class Initializer
16	{
17	    // The default width for the grid.
18	    private static final int DEFAULT_WIDTH = 120;
19	    // The default depth of the grid.
20	    private static final int DEFAULT_DEPTH = 80;
21	    // The default color for plant objects.
22	    private static final Color DEFAULT_PLANT_COLOR = Color.decode("0x006400");
23	    // Default plant name, for now there is just one type of plant so its name is default, this can be changed as the rest of the code is extendable.
24	    private static final String DEFAULT_PLANT_NAME = "plant";
25	    // The default value of if animals' ages must be randomized when thy are created.
26	    private static final boolean RANDOM_ANIMAL_AGE = true;
27	    // The names of available climate change scenarios, derived from the enum to stay in sync.
28	    private static final ArrayList<String> CLIMATE_CHANGE_SCENARIO_NAMES;
29	    static {
30	        CLIMATE_CHANGE_SCENARIO_NAMES = new ArrayList<>();
31	        for (ClimateScenarios s : ClimateScenarios.values()) {
32	            CLIMATE_CHANGE_SCENARIO_NAMES.add(s.getLabel());
33	        }
34	    }
35	    // False of the simulation starts during the day, true if it starts during the night.
36	    private static final boolean DEFAULT_START_TIME = false;
37	    // The list of colors available for animal objects.
38	    private ArrayList<Color> listOfColorsForAnimals;
39	    // The index of the next color from the list used for an animal.
40	    private int idxOfColorToUseNext;
41	    // List of species to evolve in the field.
42	    private List<Species> speciesToEvolveInSimulation;
43	    // To read habitat related data.
44	    private final HabitatCSVReader habitatReader;
45	    // To read animal related data.
46	    private final AnimalCSVReader animalReader;
47	    // To read plant related data.
48	    private final PlantCSVReader plantReader;
49	    // A Random object to handle random behaviours throughout the class.
50	    private static final Random rand = Randomizer.getRandom();
51	    // A graphical view of the simulation.
52	    private SimulatorView view;
53	    // The plant concentration in the habitat created by the user.
54	    private double habitatPlantConcentration;
55	    // The GUIHandler handling the GUI.
56	    private GUIHandler handler;
57	    /**
58	     * Builds an Initializer object and initializes its field.
59	     */
60	    public Initializer()
61	    {
62	        speciesToEvolveInSimulation = new ArrayList<>();
63	        habitatReader = new HabitatCSVReader();
64	        animalReader = new AnimalCSVReader();
65	        plantReader = new PlantCSVReader();
66	        listOfColorsForAnimals = new ArrayList<>();
67	
68	        populateAnimalColors();
69	
70	        openGUI();
71	    }
72	
73	    /**
74	     * Opens the GUI with the list of available animals and habitats extracted
75	     * from the files as well as the list of available climate change scenarios.
76	     */
77	    private void openGUI()
78	    {
79	        ArrayList<String> animalChoices = animalReader.getChoicesList();
80	        ArrayList<String> habitatChoices = habitatReader.getChoicesList();
81	        handler = new GUIHandler(this, animalChoices, habitatChoices, CLIMATE_CHANGE_SCENARIO_NAMES);
82	    }
83	
84	    /**
85	     * Create a simulator with the animals, habitat, and climate change
86	     * scenario asked by the user as well as all other necessary objects
87	     * for the simulation to run. The created Simulator is returned.
88	     *
89	     * @param chosenHabitat (String) The name of the habitat chosen by the user.
90	     * @param animalsToCreate (HashMap<String, Integer>) Keys are the animals' names and values are the number of each animal we need to create.
91	     * @param scenarioName (String) The name of the climate change scenario to implement in the simulation.
92	     * @return (Simulator) The created simulator.
93	     */
94	    public Simulator initializeSimulation(String chosenHabitat, HashMap<String, Integer> animalsToCreate, String scenarioName)
95	    {
96	        SimulationStep simulatorStepCounter = new SimulationStep();
97	        Field field = new Field(DEFAULT_DEPTH, DEFAULT_WIDTH);
98	        ClimateScenarios chosenClimateChangeScenario = ClimateScenarios.fromLabel(scenarioName);
99	        Habitat simulationHabitat = createHabitat(chosenHabitat, simulatorStepCounter, chosenClimateChangeScenario);
100	        if (simulationHabitat == null) {
101	            return null;
102	        }
103	        if (getNumberOfPlants() + getNumberOfAnimals(animalsToCreate) > calculateFieldArea()) {
104	            ErrorThrower.throwMessage("Too many animals were added for this habitat, please reduce the number of animals and try again");
105	            return null;
106	        }
107	        view = new SimulatorView(DEFAULT_DEPTH, DEFAULT_WIDTH, handler);
108	        populateWithAnimals(animalsToCreate, field);
109	        populateWithPlants(field);
110	        Time timeObject = new Time(simulatorStepCounter, DEFAULT_START_TIME);
111	        return new Simulator(simulationHabitat, timeObject ,speciesToEvolveInSimulation, field, simulatorStepCounter, view);
112	    }
113	
114	    /**
115	     * Read data for the chosen habitat and create a habitat object appropriately.
116	     *
117	     * @param habitatName (String) The name of the chosen habitat.
118	     * @param simulatorStepCounter (SimulationStep) The created SimulationStep object for this simulation to be handed to the Habitat object.
