134	    /**
135	     * Populate the simulation with the chosen animals.
136	     * First reading the data relating to each animal,
137	     * then creating and adding to the list of species the right number of each animal.
138	     *
139	     * @param animalsToCreate (HashMap<String, Integer>) The names and number of chosen animals.
140	     * @param field (Field) The field in which the animals will evolve.
141	     */
142	    private void populateWithAnimals(HashMap<String, Integer> animalsToCreate, Field field)
143	    {
144	        idxOfColorToUseNext = 0;
145	
146	        for(String animalName : animalsToCreate.keySet()) {
147	            int count = animalsToCreate.get(animalName);
148	            if (count == 0) continue;
149	
150	            animalReader.extractDataFor(animalName);
151	            String name = animalReader.getName();
152	            int maximumTemperature = animalReader.getMaximumTemperature();
153	            int minimumTemperature = animalReader.getMinimumTemperature();
154	            int maxAge = animalReader.getMaximumAge();
155	            int breedingAge = animalReader.getBreedingAge();
156	            double breedingProbability = animalReader.getBreedingProbability();
157	            int maxLitterSize = animalReader.getMaxLitterSize();
158	            int nutritionalValue = animalReader.getNutritionalValue();
159	            boolean hibernates = animalReader.canHibernate();
160	            boolean isNocturnal = animalReader.isNocturnal();
161	
162	            if (animalReader.isPredator()) {
163	                int strength = animalReader.getStrength();
164	                for (int i = 0; i < count; i++) {
165	                    Location loc = findAvailableLocation(field);
166	                    speciesToEvolveInSimulation.add(new Predator(strength, field, loc, name, maximumTemperature, minimumTemperature, nutritionalValue, breedingProbability, maxAge, breedingAge, maxLitterSize, RANDOM_ANIMAL_AGE, hibernates, isNocturnal));
167	                }
168	            }
169	            else {
170	                for (int i = 0; i < count; i++) {
171	                    Location loc = findAvailableLocation(field);
172	                    speciesToEvolveInSimulation.add(new Animal(field, loc, name, maximumTemperature, minimumTemperature, nutritionalValue, breedingProbability, maxAge, breedingAge, maxLitterSize, RANDOM_ANIMAL_AGE, hibernates, isNocturnal));
173	                }
174	            }
175	
176	            view.setColor(name, listOfColorsForAnimals.get(idxOfColorToUseNext));
177	            idxOfColorToUseNext++;
178	        }
179	    }
180	
181	    /**
182	     * Find an available location for an object to be created in the simulation field.
183	     * The simulation is chosen at random and is changed if the randomly selected cell
184	     * already contains an object.
185	     *
186	     * @param field (Field) The simulation's field.
187	     * @return (Location) the available location found.
188	     */
189	    private Location findAvailableLocation(Field field)
190	    {
191	        int randomWidth = rand.nextInt(DEFAULT_WIDTH);
192	        int randomDepth = rand.nextInt(DEFAULT_DEPTH);
193	        while (field.getObjectAt(randomDepth,randomWidth) != null) {
194	            randomWidth = rand.nextInt(DEFAULT_WIDTH);
195	            randomDepth = rand.nextInt(DEFAULT_DEPTH);
196	        }
197	        return new Location(randomDepth, randomWidth);
198	    }
199	
200	    /**
201	     * Calculate the area of the field to know the number of plants that should be created.
202	     *
203	     * @return (int) The field's area.
204	     */
205	    private int calculateFieldArea()
206	    {
207	        return DEFAULT_WIDTH * DEFAULT_DEPTH;
208	    }
209	
210	    /**
211	     * Populate the simulation with the appropriate number of plants.
212	     *
213	     * @param field (Field) The simulation's field.
214	     */
215	    private void populateWithPlants(Field field)
216	    {
217	        Location freeLocationToPlacePlant;
218	        plantReader.extractDataFor(DEFAULT_PLANT_NAME);
219	        String name = plantReader.getName();
220	        int maximumTemperature = plantReader.getMaximumTemperature();
221	        int minimumTemperature = plantReader.getMinimumTemperature();
222	        int nutritionalValue = plantReader.getNutritionalValue();
223	        double reproductionProbability = plantReader.getReproductionProbability();
