1	/**
2	 * Represent a location in a rectangular grid.
3	 *
4	 * @version 2016.02.29
5	 */
6	public class Location
7	{
8	    // Row and column positions.
9	    private final int row;
10	    private final int col;
11	
12	    /**
13	     * Represent a row and column.
14	     *
15	     * @param row The row.
16	     * @param col The column.
17	     */
18	    public Location(int row, int col)
19	    {
20	        this.row = row;
21	        this.col = col;
22	    }
23	    
24	    /**
25	     * Implement content equality.
26	     */
27	    public boolean equals(Object obj)
28	    {
29	        if(obj instanceof Location) {
30	            Location other = (Location) obj;
31	            return row == other.getRow() && col == other.getCol();
32	        }
33	        else {
34	            return false;
35	        }
36	    }
37	    
38	    /**
39	     * Return a string of the form row,column.
40	     *
41	     * @return A string representation of the location.
42	     */
43	    public String toString()
44	    {
45	        return row + "," + col;
46	    }
47	    
48	    /**
49	     * Use the top 16 bits for the row value and the bottom for the column. Except for very big grids, this should give a
50	     * unique hash code for each (row, col) pair.
51	     *
52	     * @return A hashcode for the location.
53	     */
54	    public int hashCode()
55	    {
56	        return (row << 16) + col;
57	    }
58	    
59	    /**
60	     * @return The row.
61	     */
62	    public int getRow()
63	    {
64	        return row;
65	    }
66	    
67	    /**
68	     * @return The column.
69	     */
70	    public int getCol()
71	    {
72	        return col;
73	    }
74	}
