5	/**
6	 * A class representing the characteristics of a predator.
7	 * They are different from other animals because they eat any other
8	 * animal or predator whose strength is weaker.
9	 *
10	 * A horde of weaker predators can kill and eat a stronger predator.
11	 *
12	 *
13	 * @version 2022.03.01
14	 */
15	public class Predator extends Animal
16	{
17	    // The predator's strength, if it is strong enough it can attack other predators
18	    private final int strength;
19	
20	    /**
21	     * Create a new predator with given specifications.
22	     *
23	     * @param strength (int) the predator's strength
24	     * @param field (Field) the field where the simulation takes place
25	     * @param location (Location) the Location at which the predator should appear
26	     * @param name (String) the predator's name (its species' name)
27	     * @param maximumTemperature (int) the maximum temperature the predator can survive to
28	     * @param minimumTemperature (int) the minimum temperature an predator can survive to
29	     * @param nutritionalValue (int) the predator's nutritional value
30	     * @param reproductionProbability (double) the probability that the predator reproduces at each step after a given minimum breeding age
31	     * @param maxAge (int) the predator's life expectancy
32	     * @param breedingAge (int) the age at which predator can start to reproduce
33	     * @param maxLitterSize (int) the maximum number of children the predator can have in one reproduction
34	     * @param randomAge (boolean) whether or not predator should be created with a random age
35	     * @param hibernates (boolean) whether or not predator is able to hibernate
36	     * @param isNocturnal (boolean) whether or not predator is more active at night
37	     */
38	    public Predator (int strength, Field field, Location location, String name, int maximumTemperature, int minimumTemperature, int nutritionalValue, double reproductionProbability, int maxAge, int breedingAge, int maxLitterSize,  boolean randomAge, boolean hibernates, boolean isNocturnal)
39	    {
40	        // call to the constructor of the Animal class
41	        super(field, location, name, maximumTemperature, minimumTemperature, nutritionalValue, reproductionProbability, maxAge, breedingAge, maxLitterSize, randomAge, hibernates, isNocturnal);
42	
43	        this.strength = strength;
44	    }
45	
46	    /**
47	     * A predator's movement. It first checks if it attacked by a horde of another species of predators. If it is the case,
48	     * it dies and execution stops. If not, it first tries to reproduce, then to find a prey to eat in the neighboring cells,
49	     * and finally to move to either the cell the prey he ate was occupying or another free adjacent cell. If no adjacent cell
50	     * is available, it dies of overcrowding.
51	     *
52	     * @param newSpecies (List<Species>) A list to receive newly born animals.
53	     */
54	    protected void makeMove(List<Species> newSpecies)
55	    {
56	        ArrayList<Animal> neighboringAnimals = getNeighboringAnimalsList();
57	        checkForAttack(neighboringAnimals);
58	
59	        if (isAlive()) {
60	            if (canReproduce(neighboringAnimals)){
61	                reproduce(newSpecies);
62	            }
63	
64	            // Move towards a source of food if found.
65	            Location newLocation = null;
66	            if (canEat()) {
67	                newLocation = findFoodAndEat(neighboringAnimals);
68	            } 
69	
70	            if(newLocation == null) {
71	                // No food found - try to move to a free location.
72	                newLocation = getField().freeAdjacentLocation(getLocation());
73	            }
74	
75	            // See if it was possible to move.
76	            if(newLocation != null) {
77	                setLocation(newLocation);
78	            }
79	            else {
80	                // Overcrowding.
81	                setDead();
82	            }
83	        }
84	    }
85	
86	    /**
87	     * Tries to find a prey in one of the neighboring cell. If a prey is found, it is eaten and its location is returned.
88	     *
89	     * @param  neighboringAnimals (ArrayList<Animal>) A list of neighboring animals.
90	     * @return (Location) the location of the eaten prey, null if no prey was found.
91	     */
92	    private Location findFoodAndEat(ArrayList<Animal> neighboringAnimals)
93	    {
94	        for (Animal animal : neighboringAnimals) {
95	            if(!(animal instanceof Predator)){
96	                Location preyLocation = animal.getLocation();
97	                animal.setDead();
98	                incrementFoodLevel(animal.getNutritionalValue());
99	                return preyLocation;
100	            }
101	        }
102	        // No food found
103	        return null;
104	    }
105	
106	    /**
107	     * Check if predator if under attack from a horde of another species of predator. If a horde is attacking it and the horde's strength
108	     * is greater than the predator's one, the horde members eat it.
109	     *
110	     * @param  neighboringAnimals (ArrayList<Animal>) A list of neighboring animals.
111	     */
112	    private void checkForAttack(ArrayList<Animal> neighboringAnimals)
113	    {
114	        HashSet<String> checkedSpecies = new HashSet<>();
115	
116	        for (Animal neighbor : neighboringAnimals) {
117	            if (!(neighbor instanceof Predator)) continue;
118	            String hordeName = neighbor.getName();
119	            // Skip own species and any horde species already evaluated.
120	            if (this.getName().equals(hordeName)) continue;
121	            if (!checkedSpecies.add(hordeName)) continue;
122	
123	            ArrayList<Predator> hordeMembers = new ArrayList<>();
124	            int totalHordeStrength = 0;
125	            for (Animal candidate : neighboringAnimals) {
126	                if (candidate instanceof Predator && hordeName.equals(candidate.getName())) {
127	                    Predator hordeMember = (Predator) candidate;
128	                    totalHordeStrength += hordeMember.getStrength();
129	                    hordeMembers.add(hordeMember);
130	                }
131	            }
132	
133	            if (totalHordeStrength > strength) {
134	                attackedByHorde(hordeMembers);
135	                return;
136	            }
137	        }
138	    }
139	
140	    /**
141	     * Animal is under attack by a horde whose strength is greater than its own. It is eaten by the horde and dies. Its nutritional value
142	     * is therefore shared
143	     *
144	     * @param hordeMembers (ArrayList<Predator>) List of the predators constituting the horde.
145	     */
146	    private void attackedByHorde(ArrayList<Predator> hordeMembers)
147	    {
148	        // Sharing predator's nutritional value amongst the various horde members.
149	        int foodLevelAddedToEachHordeMember = this.getNutritionalValue() / hordeMembers.size();
150	        for (Predator predator : hordeMembers) {
151	            predator.incrementFoodLevel(foodLevelAddedToEachHordeMember);
152	        }
153	        this.setDead();
154	    }
155	
156	    /**
157	     * Creates the appropriate number of predators of the same species due to reproduction. These new predators of course share the same
158	     * features as their "parent" except the sex which is randomized, their age and foodLevel are not randomized.
159	     *
160	     * @param newOfThisKind (List<Species>) The list of species to which newborns must be added.
161	     */
162	    protected void reproduce(List<Species> newOfThisKind)
163	    {
164	        Field field = getField();
165	        if (field != null)
166	        {
167	            List<Location> free = field.getFreeAdjacentLocations(getLocation());
168	            int births = numberOfBirths();
169	            for(int b = 0; b < births && free.size() > 0; b++) {
170	                Location loc = free.remove(0);
171	                Predator young = new Predator(strength, field, loc, getName(), getMaximumTemperature(), getMinimumTemperature(), getNutritionalValue(), getReproductionProbability(), getMaxAge(), getBreedingAge(), getMaxLitterSize(),false, getHibernates(), getIsNocturnal());
172	                newOfThisKind.add(young);
173	            }
174	        }
175	    }
176	
177	    /**
178	     * Returns the predator's strength, public so that other predators can consult the strength of a pontential horde this predator could
179	     * be a part of.
180	     *
181	     * @return (int) the predator's strength.
182	     */
183	    public int getStrength() {
184	        return strength;
185	    }
186	}

