1	import java.util.List;
2	import java.util.ArrayList;
3	import java.util.Iterator;
4	
5	/**
6	 * This is the main class of the simulation, as it connects all the other classes
7	 * and runs the simulation. In general, the classes simulate a habitat in which
8	 * there are preys who feed on plants, and predators who compete for the preys.
9	 *
10	 * @version 2022.02.28
11	 */
12	public class Simulator
13	{
14	    private static final int LONG_SIMULATION_STEP_COUNT = 2000;
15	    // List of species in the field.
16	    private List<Species> species;
17	    // The current state of the field.
18	    private Field field;
19	    // keep track of the simulation steps.
20	    private SimulationStep simStep;
21	    // A graphical view of the simulation.
22	    private SimulatorView view;
23	    // keep track of the time in the simulation
24	    private Time time;
25	    // the habitat of the simulation
26	    private Habitat simulationHabitat;
27	    private boolean simulationIsOn;
28	
29	    private static final int DEFAULT_DELAY = 0;
30	
31	    /**
32	     * Construct a simulation field with default size.
33	     */
34	    public Simulator(Habitat simulationHabitat, Time time, List<Species> speciesInSimulation, Field field, SimulationStep simulationStepCounter, SimulatorView simulatorView)
35	    {
36	        this.simulationHabitat = simulationHabitat;
37	        this.time = time;
38	        this.species = speciesInSimulation;
39	        this.field = field;
40	        this.simStep = simulationStepCounter;
41	        this.view = simulatorView;
42	        this.simulationIsOn = true;
43	
44	        view.showStatus(simStep.getCurrentStep(), time.timeString(), simulationHabitat.getCurrentSeason(), simulationHabitat.getCurrentTemperature(), field);
45	    }
46	
47	
48	    /**
49	     * Run the simulation from its current state for a reasonably long period set as a class constant.
50	     */
51	    public void runLongSimulation()
52	    {
53	        simulate(LONG_SIMULATION_STEP_COUNT);
54	    }
55	    
56	    /**
57	     * Run the simulation from its current state for the given number of steps.
58	     * Stop before the given number of steps if it ceases to be viable.
59	     *
60	     * @param numSteps (int) The number of steps to run for.
61	     */
62	    public void simulate(int numSteps)
63	    {
64	        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
65	            delay(DEFAULT_DELAY);
66	            simulateOneStep();
67	        }
68	    }
69	
70	    /**
71	     * Run the simulation from its current state for a single step.
72	     * Iterate over the whole field updating the state of each specie.
73	     */
74	    public void simulateOneStep()
75	    {
76	        if (simulationIsOn) {
77	            simStep.incStep();
78	            simulationHabitat.habitatStep();
79	            time.timeStep();
80	
81	            // the following variables are added here to reduce method calls:
82	            boolean isSpring = simulationHabitat.getIsSpring();
83	            boolean isNight = time.getIsNight();
84	            int currentTemperature = simulationHabitat.getCurrentTemperature();
85	            boolean yearPassed = simulationHabitat.yearPassed();
86	            boolean seasonChanged = simulationHabitat.seasonJustChanged();
87	
88	            // Provide space for newborn species.
89	            List<Species> newSpecies = new ArrayList<>();
90	            // Let all species act.
91	            for(Iterator<Species> it = species.iterator(); it.hasNext(); )
92	            {
93	                Species specie = it.next();
94	                specie.act(newSpecies, isNight, currentTemperature, yearPassed, isSpring, seasonChanged);
95	                if(! specie.isAlive()) {
96	                    it.remove();
97	                }
98	            }
99	
100	            // Add the newly born species to the main lists.
101	            species.addAll(newSpecies);
102	            view.showStatus(simStep.getCurrentStep(), time.timeString(), simulationHabitat.getCurrentSeason(), simulationHabitat.getCurrentTemperature(), field);
103	        }
104	    }
105	
106	    /**
107	     * Reset the simulation to a starting position.
108	     */
109	    public void endSimulation()
110	    {
111	        simStep.reset();
112	        species.clear();
113	        simulationIsOn = false;
114	    }
115	
116	    /**
117	     * Pause for a given time.
118	     * @param millisec (int) The time to pause for, in milliseconds
119	     */
120	    private void delay(int millisec)
121	    {
122	        try {
123	            Thread.sleep(millisec);
124	        }
125	        catch (InterruptedException ie) {
126	            // wake up
127	        }
128	    }
129	}
