275	        {
276	            return new Dimension(gridWidth * GRID_VIEW_SCALING_FACTOR,
277	                    gridHeight * GRID_VIEW_SCALING_FACTOR);
278	        }
279	
280	        /**
281	         * Prepare for a new round of painting. Since the component may be resized, compute the scaling factor again.
282	         */
283	        public void preparePaint()
284	        {
285	            if(! size.equals(getSize())) {  // if the size has changed...
286	                size = getSize();
287	                fieldImage = fieldView.createImage(size.width, size.height);
288	                g = fieldImage.getGraphics();
289	
290	                xScale = size.width / gridWidth;
291	                if(xScale < 1) {
292	                    xScale = GRID_VIEW_SCALING_FACTOR;
293	                }
294	                yScale = size.height / gridHeight;
295	                if(yScale < 1) {
296	                    yScale = GRID_VIEW_SCALING_FACTOR;
297	                }
298	            }
299	        }
300	
301	        /**
302	         * Paint on grid location on this field in a given color.
303	         */
304	        public void drawMark(int x, int y, Color color)
305	        {
306	            g.setColor(color);
307	            g.fillRect(x * xScale, y * yScale, xScale-1, yScale-1);
308	        }
309	
310	        /**
311	         * The field view component needs to be redisplayed. Copy the internal image to screen.
312	         */
313	        public void paintComponent(Graphics g)
314	        {
315	            if(fieldImage != null) {
316	                Dimension currentSize = getSize();
317	                if(size.equals(currentSize)) {
318	                    g.drawImage(fieldImage, 0, 0, null);
319	                }
320	                else {
321	                    // Rescale the previous image.
322	                    g.drawImage(fieldImage, 0, 0, currentSize.width, currentSize.height, null);
323	                }
324	            }
325	        }
326	    }
327	}

1	import java.util.List;
2	import java.util.Random;
3	
4	/**
5	 * This is an abstract class representing all the species of
6	 * the simulation. It defines some characteristics and methods
7	 * of the species.
8	 *
9	 * @version 2022.02.28
10	 */
11	public abstract class Species
12	{
13	    // The probability for an individual to die if exposed to too high or too cold temperatures.
14	    private static final double DYING_OF_COLD_OR_HEAT_PROBABILITY = 0.8;
15	    // Whether the species is alive or not.
16	    private boolean alive;
17	    // The animal's field.
18	    private Field field;
19	    // The species' position in the field.
20	    private Location location;
21	    // The species' name
22	    private final String name;
23	    // The maximum temperature at which the species can survive
24	    private final int maximumTemperature;
25	    // The minimum temperature at which the species can survive
26	    private final int minimumTemperature;
27	    // The food value animal provides when eaten
28	    private final int nutritionalValue;
29	    // The likelihood of a specie to reproduce.
30	    private final double reproductionProbability;
31	    // A random number generator
32	    protected static final Random rand = Randomizer.getRandom();
33	
34	    /**
35	     * Create a new specie at location in field.
36	     *
37	     * @param field (Field) The field currently occupied.
38	     * @param location (Location) The location within the field.
39	     * @param name (String) The name of the specie
40	     * @param maximumTemperature (int) The maximum temperature that the specie can withstand
41	     * @param minimumTemperature (int) The minimum temperature that the specie can withstand
42	     * @param nutritionalValue (int) The nutritional value given to the specie that eats this specie
43	     * @param reproductionProbability (double) The probability that this specie will reproduce
44	     */
45	    public Species(Field field, Location location, String name, int maximumTemperature, int minimumTemperature, int nutritionalValue, double reproductionProbability)
46	    {
47	        alive = true;
48	        this.field = field;
49	        setLocation(location);
50	        this.name = name;
51	        this.maximumTemperature = maximumTemperature;
52	        this.minimumTemperature = minimumTemperature;
53	        this.nutritionalValue = nutritionalValue;
54	        this.reproductionProbability = reproductionProbability;
55	    }
56	
57	    /**
58	     * Make this animal act - that is: make it do whatever it wants/needs to do.
59	     *
60	     * @param newSpecies (List<Species>) A list to receive newly born animals.
61	     * @param isNight (boolean) If it is currently night.
62	     * @param yearPassed (boolean) If a year is passing on this step (next step is the first of a nw year).
63	     */
64	    abstract public void act(List<Species> newSpecies, boolean isNight, int temperature, boolean yearPassed, boolean isSpring, boolean seasonChanged);
65	
66	    /**
67	     * An abstract class to enforce all subclasses to make their elements reproduce
68	     *
69	     * @param newOfThisKind List of Species objects in the simulation for the newborns to be added to it
70	     */
71	    abstract void reproduce(List<Species> newOfThisKind);
72	
73	    /**
74	     * Check whether the animal is alive or not.
75	     *
76	     * @return (boolean) true if the animal is still alive.
77	     */
78	    protected boolean isAlive()
79	    {
80	        return alive;
81	    }
82	
83	    /**
84	     * Indicate that the animal is no longer alive. It is removed from the field.
85	     */
86	    protected void setDead()
87	    {
88	        alive = false;
89	        if(location != null) {
90	            field.clear(location);
91	            location = null;
92	            field = null;
93	        }
94	    }
95	
96	    /**
97	     * Return the animal's location.
98	     *
99	     * @return (Location)The animal's location.
100	     */
101	    protected Location getLocation()
102	    {
103	        return location;
104	    }
105	
106	    /**
107	     * Place the animal at the new location in the given field.
108	     *
109	     * @param newLocation (Location) The animal's new location.
110	     */
111	    protected void setLocation(Location newLocation)
112	    {
113	        if(location  != null) {
114	            field.clear(location);
115	        }
116	        location = newLocation;
117	        field.place(this, newLocation);
118	    }
119	
120	    /**
121	     * @return (Field) The animal's field.
122	     */
123	    protected Field getField()
124	    {
125	        return field;
126	    }
127	
128	    /**
129	     * Check if animal can survive the current temperature. If temperature is too low or too high, animal has a high probability of dying
130	     * (probability defined as a class constant to allow easy adjusting).
131	     *
132	     * @return (Field) The animal's field.
133	     */
134	    protected boolean survivesTemperature(int temperature)
135	    {
136	        if (temperature > maximumTemperature || temperature < minimumTemperature) {
137	            return rand.nextDouble() > DYING_OF_COLD_OR_HEAT_PROBABILITY;
138	        }
139	        return true;
140	    }
141	
142	    /**
143	     * @return (String) The specie's name.
144	     */
145	    protected String getName()
146	    {
147	        return name;
148	    }
149	
150	    /**
151	     * @return (int) The maximum temperature specie can survive to.
152	     */
153	    protected int getMaximumTemperature()
154	    {
155	        return maximumTemperature;
156	    }
157	
158	    /**
159	     * @return (int) The minimum temperature specie can survive to.
160	     */
161	    protected int getMinimumTemperature()
162	    {
163	        return minimumTemperature;
164	    }
165	
166	    /**
167	     * @return (int) The specie's nutritional value.
168	     */
169	    protected int getNutritionalValue()
170	    {
171	        return nutritionalValue;
172	    }
173	
174	    /**
175	     * @return (double) The specie's reproduction probability.
176	     */
177	    protected double getReproductionProbability()
178	    {
179	        return reproductionProbability;
180	    }
181	
182	}
